    const reconstructed =
      value.input_timestamp.timestamp_basis === "reconstructed_from_series_start";
    if (
      reconstructed !==
      (value.timestamp_base_text !== undefined &&
        value.timestamp_reconstruction_method !== undefined)
    ) {
      context.addIssue({
        code: "custom",
        path: ["timestamp_reconstruction_method"],
        message:
